use arena_scores::Board;
use std::sync::Arc;
use std::thread;

fn main() {
    let board = Board::new();
    for id in 0..8u32 {
        board.join(id, 0);
    }
    let rounds = 20_000u64;
    let mut handles = Vec::new();
    for t in 0..8u32 {
        let b = board.clone();
        handles.push(thread::spawn(move || {
            for _ in 0..rounds {
                b.award(t, 1);
                b.transfer(t, (t + 1) % 8, 2);
            }
        }));
    }
    for h in handles {
        h.join().unwrap();
    }
    let expected = 8 * rounds as i64;
    let sum: i64 = (0..8u32).map(|id| board.score(id)).sum();
    println!("total={} sum={} expected={}", board.total(), sum, expected);
    assert_eq!(board.total(), expected);
    assert_eq!(sum, expected);
    println!("OK");
}


