//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

/// One lock guards the whole board state: per-player scores and the total are
/// always updated together, so no thread can observe or write a torn state.
#[derive(Clone, Default)]
pub struct Board {
    state: Arc<Mutex<GameState>>,
}

#[derive(Default)]
struct GameState {
    players: HashMap<PlayerId, i64>,
    total: i64,
}

impl GameState {
    fn score_of(&self, id: PlayerId) -> i64 {
        match self.players.get(&id) {
            Some(score) => *score,
            None => panic!("unknown player id {id}, expected a joined player"),
        }
    }
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        let mut state = self.state.lock().unwrap();
        state.players.insert(id, score);
        state.total += score;
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let mut state = self.state.lock().unwrap();
        let score = state.score_of(id);
        state.players.insert(id, score + points);
        state.total += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        if from == to {
            return;
        }
        let mut state = self.state.lock().unwrap();
        let from_score = state.score_of(from);
        let to_score = state.score_of(to);
        state.players.insert(from, from_score - points);
        state.players.insert(to, to_score + points);
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        self.state.lock().unwrap().score_of(id)
    }

    pub fn total(&self) -> i64 {
        self.state.lock().unwrap().total
    }
}

